INSERT INTO "pages" ("slug", "title", "blocks", "status", "updated_at") VALUES
('blog-what-and-where-is-maia', 'What is Maia? Porto’s northern neighbour explained', $json$[
  {"id":21001,"type":"Hero","eyebrow":"Maia explained","title":"What is Maia? Porto’s northern neighbour explained","description":"Not a district of Porto and not just the airport: Maia is an old territory, a contemporary city and a municipality where rural memory, industry, technology and green space meet.","imageUrl":"/blog/maia-overview.webp","imageAlt":"Maia City Hall and Torre Lidador","imageCredit":"Photo: Pedrovsk · CC BY-SA 3.0 · Wikimedia Commons","imageCreditUrl":"https://commons.wikimedia.org/wiki/File:Maia_Camara_Municipal.jpg","background":"#11110f","textColor":"#ffffff","width":"content","align":"left","spacing":"large"},
  {"id":21002,"type":"Texto","eyebrow":"Start with the map","title":"A municipality six kilometres north of Porto","description":"Maia belongs to the Porto Metropolitan Area. The municipality covers 82.99 km² and has roughly 135,000 inhabitants. Its ten parishes stretch from dense metropolitan neighbourhoods to cultivated land, wooded valleys and villages that still retain a distinct identity. Metro, motorways, the international airport and the Vilar de Luz aerodrome make mobility part of Maia’s modern character.","ctaLabel":"Open the official Maia tourist map","ctaUrl":"https://visitmaia.pt/assets/files/VisitMaia_Mapa%20Tur%C3%ADstico_PT_ING.pdf","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":21003,"type":"Texto","eyebrow":"More than one centre","title":"City of Maia, Castêlo, Moreira and many local worlds","description":"The City of Maia is the civic and urban centre, marked by Torre Lidador, the Forum, metro and large public spaces. Castêlo da Maia holds the old municipal centre, museum and Quinta da Gruta. Moreira contains the airport, the ancient monastic complex and a powerful overlap of agriculture, logistics and technology. Águas Santas and Pedrouços face Porto directly; the northern parishes open into greener and more rural landscapes.","ctaLabel":"Explore Visit Maia","ctaUrl":"https://www.visitmaia.pt/","background":"#171715","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":21004,"type":"Texto","eyebrow":"What Maia is known for","title":"Work, connectivity and an identity older than the modern city","description":"For many visitors Maia is the place where their plane lands. For businesses it is a logistics, industrial and technology territory. For residents it is also parks, weekly markets, pilgrimage routes, sports, cultural programming and neighbourhood life. Understanding Maia means holding all these layers together instead of reducing it to a suburb or an airport address.","ctaLabel":"Official introduction to Maia","ctaUrl":"https://visitmaia.pt/assets/files/VisitMaia_Apresenta%C3%A7%C3%A3o_PT.pdf","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb, 'published', now()),

('blog-terra-da-maia-before-the-city', 'Terra da Maia: the territory before the city', $json$[
  {"id":21101,"type":"Hero","eyebrow":"Maia heritage","title":"Terra da Maia: the territory before the city","description":"Long before today’s municipality, the name Maia described a large territory between Porto and the Ave — and a family tied to the formation of Portugal.","imageUrl":"/blog/maia-history.webp","imageAlt":"Historic Monastery of São Salvador in Moreira da Maia","imageCredit":"Photo: Biblioteca de Arte, Fundação Calouste Gulbenkian · No known restrictions · Wikimedia Commons","imageCreditUrl":"https://commons.wikimedia.org/wiki/File:Mosteiro_de_S%C3%A3o_Salvador,_Moreira,_Maia,_Portugal_(3628354423).jpg","background":"#38291f","textColor":"#ffffff","width":"content","align":"left","spacing":"large"},
  {"id":21102,"type":"Texto","eyebrow":"The old territory","title":"A Terra da Maia was much larger than Maia","description":"Municipal history describes the medieval Terra da Maia as extending from the small city of Porto to the left bank of the River Ave. Its coastal and inland limits changed repeatedly as neighbouring municipalities grew. That older geography still helps explain shared place names, family histories and routes across today’s Maia, Matosinhos, Vila do Conde and surrounding territories.","ctaLabel":"Read the municipality’s historical overview","ctaUrl":"https://www.cm-maia.pt/pages/1165","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":21103,"type":"Texto","eyebrow":"The Mendes da Maia","title":"A local lineage inside Portugal’s origin story","description":"The Mendes da Maia were established in the region from the second half of the tenth century. Municipal sources present them as powerful regional leaders who acted alongside the first king during the emergence of an autonomous Portuguese realm. The best-known name is Gonçalo Mendes da Maia, remembered as ‘O Lidador’ — a figure suspended somewhere between documented lineage, medieval warfare and later legend.","ctaLabel":"Explore Maia’s historical notes","ctaUrl":"https://www.cm-maia.pt/viver/cultura/estorias-e-memorias/identidade-e-historia-local/maia-global-apontamentos-historicos-sobre-a-nossa-maia","background":"#171715","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":21104,"type":"Texto","eyebrow":"Five thousand years","title":"The story does not begin in the Middle Ages","description":"Archaeological material in the Museum of History and Ethnology of Terra da Maia reaches back thousands of years. Its collections connect excavated objects with the landscape and later document agricultural work, linen, cereals, water technologies and disappearing professions. This is the best place to replace heroic mythology with the longer, quieter history of everyday people.","ctaLabel":"Visit the Maia museum","ctaUrl":"https://www.visitmaia.pt/produtos-turisticos/museu-de-historia-e-etnologia-da-terra-da-maia-museu-de-territorio","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb, 'published', now()),

('blog-green-maia-parks-routes-and-water', 'Green Maia: parks, routes and the water beneath them', $json$[
  {"id":21201,"type":"Hero","eyebrow":"Green Maia","title":"Green Maia: parks, routes and the water beneath them","description":"A practical route through a romantic estate, environmental education, rural paths and a 30-hectare park built around the source of a stream.","imageUrl":"/blog/maia-green.webp","imageAlt":"The early twentieth-century house and gardens at Quinta da Gruta","imageCredit":"Photo: Maieutica · CC BY-SA 4.0 · Wikimedia Commons","imageCreditUrl":"https://commons.wikimedia.org/wiki/File:Quinta_da_Gruta_-_Frente.jpg","background":"#174f3b","textColor":"#ffffff","width":"content","align":"left","spacing":"large"},
  {"id":21202,"type":"Texto","eyebrow":"Quinta da Gruta","title":"A romantic house that kept learning new jobs","description":"The early twentieth-century estate in Castêlo da Maia was built for Adão Pacheco Pereira Polónia. It later served as a secondary school and housed the institution that became the University of Maia. Today it is the municipal environmental education centre, combining gardens, organic growing, laboratories, learning and leisure.","ctaLabel":"Official Quinta da Gruta guide","ctaUrl":"https://www.visitmaia.pt/produtos-turisticos/quinta-da-gruta","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":21203,"type":"Texto","eyebrow":"Parque de Avioso","title":"Thirty hectares around a spring","description":"Designed by landscape architect Daniel Monteiro and created in 2001, Parque de Avioso covers about 30 hectares. Inside the park rises the Ribeira de Avioso, whose waters contribute to the Arquinho, the largest tributary of the River Leça. Routes through woods, open ground and observation areas make the park useful for both exercise and understanding the local water system.","ctaLabel":"Plan a visit to Parque de Avioso","ctaUrl":"https://www.visitmaia.pt/produtos-turisticos/parque-de-avioso","background":"#171715","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":21204,"type":"Texto","eyebrow":"Rural Maia","title":"Walk the productive landscape, not only the parks","description":"The PR3 Products of the Land route is a 4.6 km circular walk from Santo Ovídio through farms, rural lanes, vernacular architecture and cultivated fields. It makes visible a side of Maia that metropolitan maps often erase: a living agricultural territory beside industry, housing and major transport infrastructure.","ctaLabel":"Official PR3 route","ctaUrl":"https://visitmaia.pt/produtos-turisticos/percursos-na-maia-pr3-rota-produtos-da-terra","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb, 'published', now()),

('blog-moreira-from-monastery-to-airport', 'Moreira da Maia: from a ninth-century monastery to an international airport', $json$[
  {"id":21301,"type":"Hero","eyebrow":"Maia gateways","title":"Moreira da Maia: from a ninth-century monastery to an international airport","description":"In one parish, monastic memory, aviation, literature, industry and everyday neighbourhood life overlap in unusually clear layers.","imageUrl":"/blog/maia-gateway.webp","imageAlt":"Terminal building at Francisco Sá Carneiro Airport in Maia","imageCredit":"Photo: Robot8A · CC BY-SA 4.0 · Wikimedia Commons","imageCreditUrl":"https://commons.wikimedia.org/wiki/File:Aeroporto_Francisco_S%C3%A1_Carneiro.jpeg","background":"#243b6b","textColor":"#ffffff","width":"content","align":"left","spacing":"large"},
  {"id":21302,"type":"Texto","eyebrow":"The old gateway","title":"A monastery documented from 872","description":"The Monastery of Divino Salvador de Moreira anchors the area’s long history. The associated Quinta do Mosteiro, recently acquired by the municipality for preservation and future public cultural use, covers more than 163,000 square metres. Municipal research connects the estate with political figures, writers and repeated visits by Eça de Queirós.","ctaLabel":"Read about Quinta do Mosteiro","ctaUrl":"https://www.visitmaia.pt/blog/quinta-do-mosteiro-sera-uma-referencia-cultural-e-patrimonial-da-regiao","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":21303,"type":"Texto","eyebrow":"The new gateway","title":"Pedras Rubras became the airport of Northern Portugal","description":"The first aircraft of Companhia de Transportes Aéreos landed at Pedras Rubras on 2 December 1945. The small airfield evolved into Francisco Sá Carneiro Airport, now a strategic gateway for Maia, metropolitan Porto, Northern Portugal and Galicia. The current terminal, designed by architect João Leal, opened in 2006 and is connected directly to the metro network.","ctaLabel":"Official airport history","ctaUrl":"https://www.visitmaia.pt/public/produtos-turisticos/aeroporto-francisco-sa-carneiro","background":"#171715","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":21304,"type":"Texto","eyebrow":"Look outside the terminal","title":"Arrival can be the beginning of a local route","description":"Moreira is not empty space between baggage claim and Porto. The conventual church, Quinta do Mosteiro, local streets and nearby green spaces sit beside logistics, international companies and the movement of the airport. It is a useful first lesson in Maia: old rural structures and global infrastructure coexist at very close range.","ctaLabel":"Airport-to-Maia visitor map","ctaUrl":"https://visitmaia.pt/assets/files/promotionalmaterial/Mapa_Aeroporto_Maia010_PT_ING_13.pdf","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb, 'published', now()),

('blog-how-to-read-maias-architecture', 'How to read Maia’s architecture', $json$[
  {"id":21401,"type":"Hero","eyebrow":"Architecture & city","title":"How to read Maia’s architecture","description":"A 92-metre tower, metro reuse, public squares and environmental projects tell the story of a municipality that made contemporary architecture part of its identity.","imageUrl":"/blog/maia-overview.webp","imageAlt":"Torre Lidador rising above Maia City Hall","imageCredit":"Photo: Pedrovsk · CC BY-SA 3.0 · Wikimedia Commons","imageCreditUrl":"https://commons.wikimedia.org/wiki/File:Maia_Camara_Municipal.jpg","background":"#3b274f","textColor":"#ffffff","width":"content","align":"left","spacing":"large"},
  {"id":21402,"type":"Texto","eyebrow":"Torre Lidador","title":"A civic building designed as an urban landmark","description":"Architect António Machado designed Torre Lidador for municipal services. Inaugurated in 2001, it rises 92 metres and is visible across the municipality. Official guided visits reach the top for a 360-degree reading of Maia and the surrounding metropolitan territory — a rare case where a working civic building also functions as a viewpoint.","ctaLabel":"Book an official tower visit","ctaUrl":"https://visitmaia.pt/experiencias/descobrir/visita-comentada-a-torre-lidador","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":21403,"type":"Texto","eyebrow":"Reuse and public space","title":"Old railway, new metro; old estate, new environmental school","description":"Castêlo da Maia’s 1932 railway station was adapted for the Metro in 2006. Nearby, Quinta da Gruta’s romantic house was transformed by architect João Álvaro Rocha for environmental education. In the city centre, Eduardo Souto de Moura’s work on Praça Dr. José Vieira de Carvalho forms part of a wider network of contemporary civic projects.","ctaLabel":"Official architecture guide","ctaUrl":"https://www.visitmaia.pt/public/turismo-cultural/arquitetura","background":"#171715","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":21404,"type":"Texto","eyebrow":"The Pirâmides","title":"A monument to becoming a city","description":"The Monument to the Maiata Community consists of thirteen square-based pyramids designed by architect Pais de Figueiredo with sculptor Zulmiro de Carvalho. Inaugurated in 1988, it commemorates Maia’s elevation to city status in 1986 and uses changes in scale and light to represent collective growth.","ctaLabel":"Read the official monument guide","ctaUrl":"https://visitmaia.pt/produtos-turisticos/monumento-a-comunidade-maiata","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb, 'published', now()),

('blog-maia-traditions-made-by-hand', 'Maia traditions: wood, linen, onions and a living romaria', $json$[
  {"id":21501,"type":"Hero","eyebrow":"Living heritage","title":"Maia traditions: wood, linen, onions and a living romaria","description":"Local identity survives through things people still make, grow, carry, celebrate and teach — not through nostalgia alone.","imageUrl":"/blog/maia-museum.webp","imageAlt":"Museum of History and Ethnology of Terra da Maia","imageCredit":"Photo: Cyberlima785 · CC BY-SA 4.0 · Wikimedia Commons","imageCreditUrl":"https://commons.wikimedia.org/wiki/File:Museu_da_Maia.jpg","background":"#8d2b20","textColor":"#ffffff","width":"content","align":"left","spacing":"large"},
  {"id":21502,"type":"Texto","eyebrow":"Santeiros da Maia","title":"Sacred sculpture as skilled work","description":"Maia’s image-makers, or santeiros, developed specialist knowledge in carving and painting religious figures. The process moves from a model to the detailed carving of clothes, faces and hands, largely in wood. The Thedim family became especially associated with this craft, linking local workshops to devotional images recognised far beyond the municipality.","ctaLabel":"Official Maia heritage presentation","ctaUrl":"https://visitmaia.pt/assets/files/VisitMaia_Apresenta%C3%A7%C3%A3o_PT.pdf","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"},
  {"id":21503,"type":"Texto","eyebrow":"Linen and fields","title":"The museum keeps the knowledge inside ordinary objects","description":"The museum’s Moreira de Figueiredo collection was assembled in Maia during the 1970s and 1980s. Around two hundred objects document rural life, including the cycles of linen and cereals, animal traction, water lifting and occupations that disappeared or changed. It is material history: how work shaped language, seasons and community.","ctaLabel":"Visit the territory museum","ctaUrl":"https://www.visitmaia.pt/produtos-turisticos/museu-de-historia-e-etnologia-da-terra-da-maia-museu-de-territorio","background":"#171715","textColor":"#ffffff","width":"narrow","align":"left","spacing":"normal"},
  {"id":21504,"type":"Texto","eyebrow":"Fairs and romarias","title":"Tradition works because people keep turning up","description":"The pilgrimage of Nossa Senhora do Bom Despacho has documented roots in the eighteenth century and remains central to the July festivities. At the end of August, Santo Ovídio and the Feira das Cebolas reconnect Castêlo da Maia with agricultural exchange: braided onions, regional food, music, processions and local associations turn historical memory into a shared present.","ctaLabel":"Discover Maia’s events","ctaUrl":"https://www.visitmaia.pt/experiencias/todoseventos","background":"#b9ff27","textColor":"#11110f","width":"narrow","align":"left","spacing":"normal"},
  {"id":21505,"type":"Texto","eyebrow":"Weekly life","title":"Go on Saturday morning","description":"The weekly Feira da Maia runs every Saturday morning in the city centre. Producers and long-established traders sell seasonal fruit and vegetables, cured meats, pulses, flowers, household textiles and clothing. It is a better introduction to local life than any abstract definition of authenticity.","ctaLabel":"Official Feira da Maia information","ctaUrl":"https://visitmaia.pt/produtos-turisticos/feira-da-maia","background":"var(--paper)","textColor":"var(--foreground)","width":"narrow","align":"left","spacing":"normal"}
]$json$::jsonb, 'published', now())
ON CONFLICT ("slug") DO NOTHING;
